<div class="plain-language-note"><span>i</span><p><b>One row is one course.</b> Enter seats against the reservation categories in that row. The live balance makes it clear when a course is short, over-allocated or ready to save. Seats in existing non-state quota pools stay protected and are included in the total.</p></div>
<?php
$activeCategoryCodes=array_values(array_map(static fn(array $category):string=>(string)$category['code'],$categories));
$generalCategoryCode='';foreach($categories as $category){if(strtolower((string)$category['code'])==='general'){$generalCategoryCode=(string)$category['code'];break;}}if($generalCategoryCode===''&&$activeCategoryCodes)$generalCategoryCode=$activeCategoryCodes[0];
$seatIntakeTotal=array_sum(array_map(static fn(array $program):int=>(int)$program['seat_capacity'],$activePrograms));
$seatAssignedTotal=array_sum(array_map(static fn(array $program):int=>(int)$program['matrix_total'],$activePrograms));
$seatDifferenceTotal=$seatIntakeTotal-$seatAssignedTotal;
?>
<?php if(!$activePrograms):?><div class="card empty-inline"><b>No active programme to configure yet.</b><span>Go back to Step 2 and select at least one programme from the catalogue.</span></div>
