<?php if($manageSeats):?><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/seats/sync') ?>" class="course-seat-form" data-course-seat-table><?= csrf_field() ?>
<div class="course-seat-table-wrap"><table class="course-seat-table"><thead><tr><th scope="col">Course</th><th scope="col">Approved intake</th><?php foreach($categories as $category):?><th scope="col" title="<?= e($category['name']) ?>"><span><?= e($category['code']) ?></span><small><?= e($category['name']) ?></small></th><?php endforeach?><th scope="col">Other pools</th><th scope="col">Allocated</th><th scope="col">Balance</th><th scope="col"><span class="sr-only">Quick actions</span></th></tr></thead><tbody>
<?php foreach($activePrograms as $program):
    $stateSeats=[];$otherPoolSeats=0;
    foreach($program['seats'] as $seat){if($seat['quota']==='state'&&in_array($seat['category'],$activeCategoryCodes,true))$stateSeats[$seat['category']]=$seat;else $otherPoolSeats+=(int)$seat['seats'];}
    $seatDifference=(int)$program['seat_capacity']-(int)$program['matrix_total'];
    $rowState=(int)$program['seat_capacity']>0&&$seatDifference===0?'is-ready':($seatDifference<0?'is-over':'is-short');
?>
<tr class="<?= $rowState ?>" data-course-seat-row data-fixed-seats="<?= $otherPoolSeats ?>"><th scope="row"><span class="course-seat-code"><?= e($program['code']) ?></span><span class="course-seat-name"><?= e($program['name']) ?></span></th><td><label><span class="sr-only">Approved intake for <?= e($program['name']) ?></span><input type="number" name="capacities[<?= (int)$program['id'] ?>]" min="1" value="<?= e($program['seat_capacity']) ?>" required data-course-capacity></label></td><?php foreach($categories as $category):$seat=$stateSeats[$category['code']]??null;$seatValue=$seat?(int)$seat['seats']:0;$filled=$seat?(int)$seat['filled_seats']:0;?><td><label><span class="sr-only"><?= e($category['name']) ?> seats for <?= e($program['name']) ?></span><input type="number" name="seats[<?= (int)$program['id'] ?>][<?= e($category['code']) ?>]" min="<?= $filled ?>" value="<?= $seatValue ?>" required data-course-seat<?= $category['code']===$generalCategoryCode?' data-general-seat':'' ?>></label><?php if($filled>0):?><small class="locked-seat"><?= number_format($filled) ?> locked</small><?php endif?></td><?php endforeach?><td><span class="other-pool-count"><?= number_format($otherPoolSeats) ?></span></td><td><strong data-course-assigned><?= number_format((int)$program['matrix_total']) ?></strong></td><td><span class="course-seat-balance <?= $rowState ?>" data-course-balance><?= (int)$program['seat_capacity']<1?'Set intake':($seatDifference===0?'Ready':($seatDifference>0?'+'.number_format($seatDifference):number_format($seatDifference))) ?></span></td><td><button type="button" class="text-button" data-fill-general <?= $generalCategoryCode===''?'disabled':'' ?>>Fill General</button></td></tr>
<?php endforeach?></tbody></table></div>
<div class="course-seat-form-footer"><div><b>Check every row before saving</b><small>“Fill General” assigns the remaining seats in that course to the General category. Existing non-state quota seats remain included but are not changed here.</small></div><button class="button button-primary">Save course-wise seat matrix</button></div>
</form><?php else:?><div class="course-seat-table-wrap"><table class="course-seat-table is-read-only"><thead><tr><th>Course</th><th>Approved intake</th><?php foreach($categories as $category):?><th title="<?= e($category['name']) ?>"><?= e($category['code']) ?></th><?php endforeach?><th>Other pools</th><th>Allocated</th><th>Balance</th></tr></thead><tbody><?php foreach($activePrograms as $program):$stateSeats=[];$otherPoolSeats=0;foreach($program['seats'] as $seat){if($seat['quota']==='state'&&in_array($seat['category'],$activeCategoryCodes,true))$stateSeats[$seat['category']]=$seat;else $otherPoolSeats+=(int)$seat['seats'];}$seatDifference=(int)$program['seat_capacity']-(int)$program['matrix_total'];?>
<tr><th scope="row"><span class="course-seat-code"><?= e($program['code']) ?></span><span class="course-seat-name"><?= e($program['name']) ?></span></th><td><?= number_format((int)$program['seat_capacity']) ?></td><?php foreach($categories as $category):?><td><?= number_format((int)($stateSeats[$category['code']]['seats']??0)) ?></td><?php endforeach?><td><?= number_format($otherPoolSeats) ?></td><td><?= number_format((int)$program['matrix_total']) ?></td><td><?= $seatDifference===0?'Ready':e((string)$seatDifference) ?></td></tr><?php endforeach?></tbody></table></div><?php endif?>
<?php endif?>
