span>Display order</span><input type="number" name="sort_order" value="100"></label><label><span>Built-in data connection</span><input name="canonical_binding" placeholder="Leave blank for a custom question"></label><label class="full"><span>Show only when (JSON)</span><textarea name="conditional_rules" placeholder='{"field":"category","operator":"eq","value":"SC"}'></textarea></label><label class="check-control"><input type="checkbox" name="is_searchable" value="1"><span>Allow staff search/filter use</span></label></div></details><button class="button button-primary">Add question</button></form></details><?php endif?>
